/**
 * Fixed phrases (docs/legal/textos/07 section E). Not generated by the model: they are loaded into the agent as
 * literal text and used by the engine for the hard cut. es-ES falls back to es-419 where the file gives no variant.
 */
import type { Language } from "../types";

export type PhraseId = "E-01" | "E-02" | "D-01" | "D-02" | "D-03" | "D-04" | "D-05" | "D-06";

type Variants = Partial<Record<Language, string>> & { "es-419": string; en: string };

export const PHRASES: Record<PhraseId, Variants> = {
  "E-01": {
    "es-419": "Soy la voz mágica de Santa, hecha con computadora, ¡y la magia de la Navidad es muy real!",
    "es-ES": "Soy la voz mágica de Papá Noel, hecha con ordenador, ¡y la magia de la Navidad es muy real!",
    en: "I'm the magic voice of Santa, made with a computer, and the magic of Christmas is very real!",
  },
  "E-02": {
    "es-419": "Sí, soy una voz de computadora, una inteligencia artificial. ¡Pero me encanta hablar contigo!",
    en: "Yes, I'm a computer voice, an artificial intelligence. But I love talking with you!",
  },
  "D-01": {
    "es-419": "Eso guárdalo para tu familia. Mejor cuéntame, ¿qué te gusta hacer en Navidad?",
    "es-ES": "Eso guárdaselo a tu familia. Mejor cuéntame, ¿qué te gusta hacer en Navidad?",
    en: "Keep that for your family. Tell me instead, what do you like to do at Christmas?",
  },
  "D-02": {
    "es-419": "Ha sido muy bonito hablar contigo, {{NOMBRE_NIÑO}}. ¡Hasta pronto!",
    en: "It was lovely talking with you, {{NOMBRE_NIÑO}}. Goodbye!",
  },
  "D-03": {
    "es-419": "Hola, soy la voz de inteligencia artificial de {{MARCA}}. ¿Quiere que terminemos la llamada o que continúe con {{NOMBRE_NIÑO}}?",
    en: "Hello, this is the artificial intelligence voice of {{MARCA}}. Would you like me to end the call or continue with {{NOMBRE_NIÑO}}?",
  },
  "D-04": {
    "es-419": "Entendido. Terminamos aquí y no volveremos a llamar a este número. Que tengan un buen día.",
    en: "Understood. We will end here and will not call this number again. Have a good day.",
  },
  "D-05": {
    "es-419": "Gracias por contármelo. Lo que sientes es importante: cuéntaselo ahora mismo a un adulto de confianza, como mamá, papá o alguien de tu familia. Si necesitas ayuda urgente, que un adulto llame al número de emergencias. Adiós.",
    en: "Thank you for telling me. What you feel is important: tell a trusted adult right now, like mom, dad or someone in your family. If you need urgent help, ask an adult to call emergency services. Goodbye.",
  },
  "D-06": {
    "es-419": "Disculpe la molestia. Alguien pidió esta llamada para un niño; si usted no la esperaba, terminamos aquí y no volveremos a llamar a este número.",
    en: "Sorry to bother you. Someone requested this call for a child; if you were not expecting it, we will end here and will not call this number again.",
  },
};

export function phrase(id: PhraseId, language: Language): string {
  const v = PHRASES[id];
  return v[language] ?? (language === "es-ES" ? v["es-419"] : v.en);
}
